using Scripts.Data.Entities;
using Microsoft.EntityFrameworkCore;
using Microsoft.EntityFrameworkCore.ChangeTracking;
using Microsoft.EntityFrameworkCore.Storage.ValueConversion;

namespace Scripts.Data;

internal sealed class ScriptsDbContext : DbContext
{
	public ScriptsDbContext(DbContextOptions<ScriptsDbContext> options)
		: base(options: options) =>
		ChangeTracker.QueryTrackingBehavior = QueryTrackingBehavior.NoTracking;

	protected override void OnConfiguring(DbContextOptionsBuilder optionsBuilder)
	{
		base.OnConfiguring(optionsBuilder);
		// Compiled model breaks InMemory provider (missing key comparers); use OnModelCreating instead.
		var inMemory = optionsBuilder.Options.Extensions
			.Any(e => e.GetType().FullName?.Contains("InMemoryOptionsExtension") == true);

using Scripts.Data.Repositories;
using Microsoft.Extensions.DependencyInjection;

namespace Scripts.Data;

internal static class DbContextRegistration
{
	public static IServiceCollection AddScriptsDbContext(this IServiceCollection services)
	{
		var connStr =
			GetEnvironmentVariable(variable: "PGCONNSTR") ?? Variables.DefaultConnectionString;

		services.AddDbContext<ScriptsDbContext>(opts => opts.UseNpgsql(connectionString: connStr));
		services.AddRepositories();

		return services;
	}
}

using Microsoft.EntityFrameworkCore.Design;

namespace Scripts.Data;

internal sealed class ScriptsDbContextFactory : IDesignTimeDbContextFactory<ScriptsDbContext>
{
	public ScriptsDbContext CreateDbContext(string[] args)
	{
		DbContextOptionsBuilder<ScriptsDbContext> optionsBuilder = new();
		var connStr =
			GetEnvironmentVariable(variable: "PGCONNSTR") ?? Variables.DefaultConnectionString;

		optionsBuilder.UseNpgsql(connectionString: connStr);
		return new ScriptsDbContext(options: optionsBuilder.Options);
	}
}

